import{_ as l,C as c,o as n,c as b,j as t,a as e,E as o,a5 as r}from"./chunks/framework.Dep_XxFZ.js";const E=JSON.parse('{"title":"就地编辑","description":"","frontmatter":{},"headers":[],"relativePath":"components/editable.md","filePath":"components/editable.md","lastUpdated":1787359578000}'),h={name:"components/editable.md"},s={id:"就地编辑",tabindex:"-1"};function u(p,d,g,x,m,v){const i=c("Badge"),a=c("XhDemo");return n(),b("div",null,[t("h1",s,[d[0]||(d[0]=e("就地编辑 ",-1)),o(i,{type:"info",text:"editable"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#就地编辑","aria-label":'Permalink to "就地编辑 <Badge type="info" text="editable" />"'},"​",-1))]),d[3]||(d[3]=r('<p>一段文本平时是只读的展示，点一下就地变成输入框。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>标题、备注这类偶尔才改的单值，不值得为它单开一个表单。</li><li>表格单元格的快速修改。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>一次要改很多字段：打开表单或<a href="./dialog">对话框</a>。</li><li>值需要复杂校验或多步确认。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>submitMode</code> 决定回车、失焦还是显式按钮提交。</li><li><code>activationMode</code> 决定单击、双击还是只能按编辑按钮进编辑态。</li><li>三个回调分开：提交、还原、编辑态变化。</li><li><code>autoResize</code> 让输入框跟着内容长。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>预览与编辑两态轮流上场：点预览区或按「编辑」进编辑态，preview 不写内容、显示什么由组件填</p>',10)),o(a,{src:"editable/01-basic"}),d[4]||(d[4]=t("h3",{id:"提交方式",tabindex:"-1"},[e("提交方式 "),t("a",{class:"header-anchor",href:"#提交方式","aria-label":'Permalink to "提交方式"'},"​")],-1)),d[5]||(d[5]=t("p",null,"submitMode 决定编辑态怎么收尾，不算提交的那些出口一律按撤销处理，值还回上一次提交的那个",-1)),o(a,{src:"editable/02-submit-mode"}),d[6]||(d[6]=t("h3",{id:"受控",tabindex:"-1"},[e("受控 "),t("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),d[7]||(d[7]=t("p",null,"value 与 edit 都能受控，传了就由宿主说了算，用户交互只发出意图；外部按钮同样进得了编辑态",-1)),o(a,{src:"editable/03-controlled"}),d[8]||(d[8]=t("h3",{id:"禁用与只读",tabindex:"-1"},[e("禁用与只读 "),t("a",{class:"header-anchor",href:"#禁用与只读","aria-label":'Permalink to "禁用与只读"'},"​")],-1)),d[9]||(d[9]=t("p",null,"两者都进不了编辑态；值为空时预览区退回压淡的占位文字",-1)),o(a,{src:"editable/04-disabled"}),d[10]||(d[10]=t("h3",{id:"表格里的单元格",tabindex:"-1"},[e("表格里的单元格 "),t("a",{class:"header-anchor",href:"#表格里的单元格","aria-label":'Permalink to "表格里的单元格"'},"​")],-1)),d[11]||(d[11]=t("p",null,"一格一个就地编辑：点开就是输入框，收尾即写回行数据；autoResize 让输入框按内容宽窄走，不把列撑变形",-1)),o(a,{src:"editable/05-table-cell"}),d[12]||(d[12]=t("h3",{id:"整表进出编辑态",tabindex:"-1"},[e("整表进出编辑态 "),t("a",{class:"header-anchor",href:"#整表进出编辑态","aria-label":'Permalink to "整表进出编辑态"'},"​")],-1)),d[13]||(d[13]=t("p",null,"edit 受控就由宿主统一调度：一个开关把整张表切进编辑，放弃时宿主拿自己留的底稿还原",-1)),o(a,{src:"editable/06-switchable"}),d[14]||(d[14]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-editable&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhEditableArea</code> <code>XhEditableCancelTrigger</code> <code>XhEditableControl</code> <code>XhEditableEditTrigger</code> <code>XhEditableInput</code> <code>XhEditableLabel</code> <code>XhEditablePreview</code> <code>XhEditableRoot</code> <code>XhEditableSubmitTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useEditable</code></td></tr><tr><td>状态机</td><td><code>editableMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/editable.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;editable&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <code>area</code> · <strong><code>preview</code></strong> · <strong><code>input</code></strong> · <code>edit-trigger</code> · <code>submit-trigger</code> · <code>cancel-trigger</code> · <code>control</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td></td><td>受控值；给了就由宿主说了算，机器不自改（cell 原生受控，无影子事件）。</td></tr><tr><td><code>defaultValue</code></td><td><code>string</code></td><td></td><td>非受控初值。</td></tr><tr><td><code>edit</code></td><td><code>boolean</code></td><td></td><td>受控编辑态；给了就由宿主说了算，用户交互只发 onEditChange。</td></tr><tr><td><code>defaultEdit</code></td><td><code>boolean</code></td><td></td><td>非受控初始编辑态。为真时挂载即进编辑态并把焦点搬进输入框。</td></tr><tr><td><code>placeholder</code></td><td><code>string</code></td><td></td><td>值为空时预览区显示它，输入框也拿它当占位。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>禁用：进不了编辑态，输入框带原生 disabled。</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：进不了编辑态，但已在编辑态时仍能退出（撤销/提交都通）。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败标注。</td></tr><tr><td><code>maxLength</code></td><td><code>number</code></td><td></td><td>字符数上限；同时落成原生 maxlength 与机器侧截断。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名；给了输入框才参与提交。</td></tr><tr><td><code>submitMode</code></td><td><code>EditableSubmitMode</code></td><td></td><td>编辑态的收尾方式，默认 both。</td></tr><tr><td><code>activationMode</code></td><td><code>EditableActivationMode</code></td><td></td><td>预览区的激活方式，默认 click。</td></tr><tr><td><code>selectOnFocus</code></td><td><code>boolean</code></td><td></td><td>进编辑态时全选已有内容，默认开。关掉则光标停在原处。</td></tr><tr><td><code>autoResize</code></td><td><code>boolean</code></td><td></td><td>输入框宽度跟着内容走：连接层把字符数落成原生 size 属性。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: EditableValueChangeDetails) =&gt; void</code></td><td></td><td>值变化意图回调；编辑途中每次输入都发，受控时是唯一出口。</td></tr><tr><td><code>onValueCommit</code></td><td><code>(details: EditableValueCommitDetails) =&gt; void</code></td><td></td><td>提交那一刻才发；编辑途中的输入不会惊动它。</td></tr><tr><td><code>onValueRevert</code></td><td><code>(details: EditableValueRevertDetails) =&gt; void</code></td><td></td><td>撤销那一刻发（Escape、取消按钮、不算提交的离场）。</td></tr><tr><td><code>onEditChange</code></td><td><code>(details: EditableEditChangeDetails) =&gt; void</code></td><td></td><td>编辑态变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>EditableValueChangeDetails</code></td><td>编辑途中的值变化；detail 为 <code>{ value: string }</code></td></tr><tr><td><code>value-commit</code></td><td><code>EditableValueCommitDetails</code></td><td>提交；detail 为 <code>{ value: string, previousValue: string }</code></td></tr><tr><td><code>value-revert</code></td><td><code>EditableValueRevertDetails</code></td><td>撤销；detail 为 <code>{ value: string, discardedValue: string }</code></td></tr><tr><td><code>edit-change</code></td><td><code>EditableEditChangeDetails</code></td><td>编辑态变化；detail 为 <code>{ edit: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhEditableRoot</code></td><td><code>default</code></td><td><code>EditableRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>label</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>area</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>preview</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>input</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>edit-trigger</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>submit-trigger</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>cancel-trigger</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>control</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>preview</code> · <code>edit</code></p><p><strong>事件</strong>：<code>EDIT.START</code> · <code>EDIT.SUBMIT</code> · <code>EDIT.CANCEL</code> · <code>EDIT.LEAVE</code> · <code>VALUE.SET</code> · <code>CONTROLLED.EDIT</code> · <code>CONTROLLED.PREVIEW</code> · <code>FORM.RESET</code></p><p><strong>判据</strong>：<code>isEditControlled</code> · <code>canEdit</code> · <code>submitsOnLeave</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useEditable</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string</code></td><td>当下的值（编辑途中就是输入框里的那串）。</td></tr><tr><td><code>committedValue</code></td><td><code>string</code></td><td>上一次提交的值，也是撤销的落点。</td></tr><tr><td><code>editing</code></td><td><code>boolean</code></td><td>正处在编辑态。</td></tr><tr><td><code>empty</code></td><td><code>boolean</code></td><td>值为空串。</td></tr><tr><td><code>displayValue</code></td><td><code>string</code></td><td>预览区当下该显示的文字：值为空时退回 placeholder。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>interactive</code></td><td><code>boolean</code></td><td>进得了编辑态（既没禁用也不只读）。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string) =&gt; void</code></td><td>直接写值，只受 disabled/readOnly 与 maxLength 约束，与编辑态无关。</td></tr><tr><td><code>edit</code></td><td><code>() =&gt; void</code></td><td>进编辑态；禁用或只读时不动。</td></tr><tr><td><code>submit</code></td><td><code>() =&gt; void</code></td><td>提交当下的值并回到预览态。</td></tr><tr><td><code>cancel</code></td><td><code>() =&gt; void</code></td><td>撤销回上一次提交的值并回到预览态。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;label&#39;]</code></td><td></td></tr><tr><td><code>getAreaProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPreviewProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getInputProps</code></td><td><code>() =&gt; T[&#39;input&#39;]</code></td><td></td></tr><tr><td><code>getEditTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getSubmitTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getCancelTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getControlProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://html.spec.whatwg.org/multipage/input.html#text-(type=text)-state-and-search-state-(type=search)" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>focus in input, submitMode 为 enter 或 both</td><td>提交当下的值并回到预览态；其余模式不接管该键，交回给浏览器与外层表单</td></tr><tr><td><code>Escape</code></td><td>focus in input</td><td>撤销回上一次提交的值并回到预览态</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus in input</td><td>按 submitMode 收尾（blur/both 提交，enter/none 撤销）；不拦默认行为，焦点照常移出</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>preview</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>input</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>edit-trigger</code></td><td><code>aria-controls</code></td><td><code>input</code> 部件的 id</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/editable.css</code> 按部件选择：<code>[data-scope=&quot;editable&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>label</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>area</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>area</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>area</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>preview</code></td><td><code>data-activation-mode</code></td><td>props.activationMode</td></tr><tr><td><code>preview</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>preview</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>preview</code></td><td><code>data-placeholder</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>preview</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>preview</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>input</code></td><td><code>data-auto-resize</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>input</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>edit-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>edit-trigger</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>submit-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>submit-trigger</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>cancel-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>cancel-trigger</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr><tr><td><code>control</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>control</code></td><td><code>data-state</code></td><td>&#39;edit&#39; | &#39;preview&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-editable-area-min-h</code> · <code>--xh-editable-area-min-w</code> · <code>--xh-editable-control-gap</code> · <code>--xh-editable-gap</code> · <code>--xh-editable-input-bg</code> · <code>--xh-editable-input-bg-disabled</code> · <code>--xh-editable-input-bg-readonly</code> · <code>--xh-editable-input-border</code> · <code>--xh-editable-input-border-focus</code> · <code>--xh-editable-input-border-hover</code> · <code>--xh-editable-input-border-invalid</code> · <code>--xh-editable-input-fg</code> · <code>--xh-editable-input-font-size</code> · <code>--xh-editable-input-h</code> · <code>--xh-editable-input-px</code> · <code>--xh-editable-input-radius</code> · <code>--xh-editable-label-fg</code> · <code>--xh-editable-label-fg-disabled</code> · <code>--xh-editable-label-font-size</code> · <code>--xh-editable-label-font-weight</code> · <code>--xh-editable-placeholder-fg</code> · <code>--xh-editable-preview-bg-hover</code> · <code>--xh-editable-preview-fg</code> · <code>--xh-editable-preview-font-size</code> · <code>--xh-editable-preview-min-h</code> · <code>--xh-editable-preview-px</code> · <code>--xh-editable-preview-radius</code> · <code>--xh-editable-submit-bg</code> · <code>--xh-editable-submit-bg-active</code> · <code>--xh-editable-submit-bg-hover</code> · <code>--xh-editable-submit-border</code> · <code>--xh-editable-submit-border-active</code> · <code>--xh-editable-submit-border-hover</code> · <code>--xh-editable-submit-fg</code> · <code>--xh-editable-trigger-bg</code> · <code>--xh-editable-trigger-bg-active</code> · <code>--xh-editable-trigger-bg-disabled</code> · <code>--xh-editable-trigger-bg-hover</code> · <code>--xh-editable-trigger-border</code> · <code>--xh-editable-trigger-border-disabled</code> · <code>--xh-editable-trigger-border-hover</code> · <code>--xh-editable-trigger-fg</code> · <code>--xh-editable-trigger-font-size</code> · <code>--xh-editable-trigger-h</code> · <code>--xh-editable-trigger-px</code> · <code>--xh-editable-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放进<a href="./table">表格</a>的单元格；与<a href="./form">表单</a>配合做整表进出编辑态。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>展示态要有可编辑的暗示（悬停时的底色或一枚铅笔），否则没人知道能点。</li><li>Escape 一定要能取消，且还原成原值。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>失焦即提交却没有撤销：用户点到别处就把改动落库了。</li><li>展示态和编辑态的行高不一样，进出编辑时整行跳动。</li></ul>',48))])}const P=l(h,[["render",u]]);export{E as __pageData,P as default};
